import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import styled from 'styled-components';

const PageContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const RecipeHeader = styled.div`
  display: flex;
  flex-direction: column;
  margin-bottom: 40px;
  
  @media (min-width: 992px) {
    flex-direction: row;
    gap: 40px;
  }
`;

const RecipeImageContainer = styled.div`
  flex: 1;
  margin-bottom: 30px;
  
  @media (min-width: 992px) {
    margin-bottom: 0;
  }
`;

const RecipeImage = styled.img`
  width: 100%;
  border-radius: 12px;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  height: 400px;
  object-fit: cover;
`;

const RecipeInfo = styled.div`
  flex: 1;
`;

const RecipeTitle = styled.h1`
  color: #333;
  margin-bottom: 15px;
  position: relative;
  font-size: 2.5rem;
  
  &:after {
    content: '';
    display: block;
    width: 80px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 15px 0;
    border-radius: 3px;
  }
`;

const RecipeDescription = styled.p`
  color: #555;
  font-size: 1.2rem;
  line-height: 1.6;
  margin-bottom: 25px;
`;

const RecipeMeta = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  margin-bottom: 25px;
`;

const MetaItem = styled.div`
  background-color: #f8f8f8;
  padding: 12px 20px;
  border-radius: 30px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  color: #555;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
`;

const RecipeDifficulty = styled.div`
  display: inline-block;
  padding: 8px 16px;
  border-radius: 20px;
  font-size: 0.9rem;
  font-weight: 500;
  margin-bottom: 25px;
  
  &.easy {
    background-color: #8BC34A;
    color: white;
  }
  
  &.medium {
    background-color: #FFC107;
    color: white;
  }
  
  &.hard {
    background-color: #FF5722;
    color: white;
  }
`;

const RecipePrice = styled.div`
  font-size: 1.4rem;
  font-weight: 600;
  color: #4CAF50;
  margin-bottom: 25px;
  padding: 15px 0;
  border-top: 1px solid #eee;
  border-bottom: 1px solid #eee;
`;

const RecipeAuthor = styled.div`
  font-style: italic;
  color: #777;
  margin-bottom: 25px;
`;

const CategoryTag = styled(Link)`
  display: inline-block;
  background-color: #f0f0f0;
  color: #555;
  padding: 8px 15px;
  border-radius: 20px;
  margin-right: 10px;
  margin-bottom: 10px;
  text-decoration: none;
  font-size: 0.9rem;
  transition: all 0.3s;
  
  &:hover {
    background-color: #4CAF50;
    color: white;
  }
`;

const RecipeTabs = styled.div`
  margin-bottom: 40px;
`;

const TabsHeader = styled.div`
  display: flex;
  border-bottom: 1px solid #ddd;
  margin-bottom: 25px;
`;

const TabButton = styled.button`
  padding: 15px 30px;
  background-color: ${props => props.active ? '#4CAF50' : 'transparent'};
  color: ${props => props.active ? 'white' : '#555'};
  border: none;
  cursor: pointer;
  font-size: 1.1rem;
  font-weight: 500;
  transition: all 0.3s;
  
  &:hover {
    background-color: ${props => props.active ? '#45a049' : '#f0f0f0'};
  }
`;

const TabContent = styled.div`
  display: ${props => props.active ? 'block' : 'none'};
`;

const IngredientsSection = styled.div`
  margin-bottom: 30px;
`;

const SectionTitle = styled.h3`
  color: #333;
  margin-bottom: 20px;
  position: relative;
  display: inline-block;
  
  &:after {
    content: '';
    display: block;
    width: 40px;
    height: 2px;
    background: #4CAF50;
    margin-top: 10px;
  }
`;

const IngredientsList = styled.ul`
  list-style-type: none;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 15px;
`;

const IngredientItem = styled.li`
  display: flex;
  align-items: center;
  padding: 12px 15px;
  background-color: #f8f8f8;
  border-radius: 8px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
  
  &:before {
    content: "•";
    color: #4CAF50;
    font-weight: bold;
    margin-right: 10px;
    font-size: 1.2rem;
  }
`;

const InstructionsSection = styled.div``;

const StepsList = styled.ol`
  padding-left: 20px;
  counter-reset: steps;
`;

const StepItem = styled.li`
  margin-bottom: 25px;
  position: relative;
  padding-left: 40px;
  counter-increment: steps;
  
  &:before {
    content: counter(steps);
    position: absolute;
    left: 0;
    top: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    width: 30px;
    height: 30px;
    background-color: #4CAF50;
    color: white;
    border-radius: 50%;
    font-weight: bold;
  }
`;

const NutritionSection = styled.div``;

const NutritionTable = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
`;

const TableRow = styled.tr`
  border-bottom: 1px solid #eee;
  
  &:last-child {
    border-bottom: none;
  }
`;

const TableCell = styled.td`
  padding: 12px;
`;

const TableHeader = styled.th`
  text-align: left;
  padding: 12px;
  background-color: #f8f8f8;
`;

const RelatedRecipes = styled.div`
  margin-top: 60px;
`;

const RelatedTitle = styled.h2`
  color: #333;
  margin-bottom: 30px;
  position: relative;
  display: inline-block;
  
  &:after {
    content: '';
    display: block;
    width: 60px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin-top: 15px;
  }
`;

const RecipesGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const RecipeCard = styled.div`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const RecipeCardImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const RecipeCardContent = styled.div`
  padding: 20px;
`;

const RecipeCardTitle = styled.h3`
  margin: 0 0 10px 0;
  font-size: 1.2rem;
  color: #333;
`;

const ViewRecipeButton = styled(Link)`
  display: block;
  background-color: #4CAF50;
  color: white;
  text-align: center;
  text-decoration: none;
  padding: 10px 0;
  border-radius: 6px;
  font-weight: 600;
  margin-top: 15px;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-3px);
  }
`;

const RecipeDetailPage = () => {
  const { recipeId } = useParams();
  const [recipe, setRecipe] = useState(null);
  const [relatedRecipes, setRelatedRecipes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('ingredients');
  
  // Örnek tarif verileri - Gerçek uygulamada API'den alınacak
  const exampleRecipes = [
    {
      id: "1",
      title: 'Ev Yapımı Lazanya',
      image: 'https://images.unsplash.com/photo-1574894709920-11b28e7367e3?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'medium',
      time: '45 dk',
      servings: '4-6 kişilik',
      description: 'Lezzetli ve doyurucu ev yapımı lazanya. İtalyan mutfağının bu klasik lezzeti herkesi memnun edecek.',
      price: '₺120',
      categories: [{id: 'ana-yemekler', name: 'Ana Yemekler'}, {id: 'dunya-mutfagi', name: 'Dünya Mutfağı'}],
      author: 'Ayşe Yılmaz',
      date: '2023-03-15',
      ingredients: [
        '500g kıyma',
        '1 paket lazanya yaprağı',
        '2 adet soğan',
        '2 diş sarımsak',
        '2 adet domates',
        '2 yemek kaşığı domates salçası',
        '400g kaşar peyniri',
        '200g lor peyniri',
        '1 su bardağı süt',
        '2 yemek kaşığı tereyağı',
        '2 yemek kaşığı un',
        'Tuz, karabiber, kekik',
        'Zeytinyağı'
      ],
      instructions: [
        'Soğanı ve sarımsağı ince ince doğrayın. Domatesleri küp küp kesin.',
        'Geniş bir tavada zeytinyağını ısıtın. Soğan ve sarımsağı pembeleşene kadar kavurun.',
        'Kıymayı ekleyip, rengi değişene kadar kavurun.',
        'Domates ve salçayı ekleyin, orta ateşte 15-20 dakika pişirin.',
        'Tuz, karabiber ve kekik ile tatlandırın. Sosu bir kenara alın.',
        'Beşamel sos için, küçük bir tencerede tereyağını eritin.',
        'Unu ekleyip, 1-2 dakika karıştırarak kavurun.',
        'Sütü yavaş yavaş ekleyerek, topaklanma olmaması için sürekli karıştırın.',
        'Sos koyulaşınca, tuz ve karabiber ekleyin.',
        'Fırın kabını yağlayın. Kabın dibine bir miktar beşamel sos yayın.',
        'İlk kat lazanya yapraklarını yerleştirin.',
        'Üzerine kıymalı sos, beşamel sos ve rendelenmiş kaşar peyniri sırayla ekleyin.',
        'Bu katları bitene kadar tekrarlayın. En üste bolca kaşar peyniri rendeleyin.',
        'Önceden 180°C ısıtılmış fırında, üzeri kızarana kadar yaklaşık 25-30 dakika pişirin.',
        'Fırından çıkarıp 10 dakika dinlendirdikten sonra servis yapın.'
      ],
      nutrition: {
        calories: '450 kcal',
        fat: '25g',
        protein: '30g',
        carbs: '35g',
        fiber: '3g',
        sugar: '5g'
      }
    },
    {
      id: "2",
      title: 'Köfte Patates',
      image: 'https://images.unsplash.com/photo-1529042410759-befb1204b468?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'easy',
      time: '30 dk',
      servings: '4 kişilik',
      description: 'Yer sofraların vazgeçilmezi, pratik ve lezzetli bir tarif. Çocukların en sevdiği yemeklerden biri.',
      price: '₺85',
      categories: [{id: 'ana-yemekler', name: 'Ana Yemekler'}],
      author: 'Mehmet Demir',
      date: '2023-03-10',
      ingredients: [
        '500g kıyma',
        '1 adet soğan',
        '2 diş sarımsak',
        '1/2 demet maydanoz',
        '1 adet yumurta',
        '4-5 adet orta boy patates',
        '2 yemek kaşığı galeta unu',
        'Tuz, karabiber, kırmızı biber, kimyon',
        'Zeytinyağı'
      ],
      instructions: [
        'Soğan ve sarımsağı ince ince doğrayın, maydanozu kıyın.',
        'Kıymanın içine soğan, sarımsak, maydanoz, yumurta, galeta unu ve baharatları ekleyin.',
        'Güzelce yoğurun ve 15 dakika buzdolabında dinlendirin.',
        'Patatesleri yıkayıp soyun ve küp küp doğrayın.',
        'Geniş bir tavada zeytinyağını ısıtın ve patatesleri kızarana kadar pişirin.',
        'Kıymadan ceviz büyüklüğünde parçalar koparıp yuvarlak köfteler hazırlayın.',
        'Başka bir tavada köfteleri her iki tarafı da kızarana kadar pişirin.',
        'Kızaran köfteleri patateslerin üzerine ekleyin.',
        'Kapağı kapatıp 5 dakika daha pişirin. Sıcak servis yapın.'
      ],
      nutrition: {
        calories: '380 kcal',
        fat: '20g',
        protein: '25g',
        carbs: '28g',
        fiber: '2g',
        sugar: '2g'
      }
    },
    {
      id: "7",
      title: 'Çikolatalı Brownie',
      image: 'https://images.unsplash.com/photo-1564355808539-22fda35bed7e?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80',
      difficulty: 'medium',
      time: '35 dk',
      servings: '8 dilim',
      description: 'Dışı çıtır içi yumuşacık, bol çikolatalı brownie. Tatlı krizlerinin kurtarıcısı.',
      price: '₺70',
      categories: [{id: 'tatlilar', name: 'Tatlılar'}],
      author: 'Selin Yıldız',
      date: '2023-03-12',
      ingredients: [
        '200g bitter çikolata',
        '150g tereyağı',
        '3 adet yumurta',
        '1 su bardağı toz şeker',
        '1 paket vanilya',
        '1/2 çay kaşığı tuz',
        '3/4 su bardağı un',
        '1/4 su bardağı kakao',
        '100g çikolata parçaları (isteğe bağlı)'
      ],
      instructions: [
        'Fırını 180°C ısıtın. Kare bir fırın kabını yağlayın veya pişirme kağıdı serin.',
        'Çikolatayı ve tereyağını bir kap içinde benmari usulü eritin.',
        'Başka bir kapta yumurtaları ve şekeri krema kıvamına gelene kadar çırpın.',
        'Eriyen çikolatalı karışımı yumurtalı karışıma ekleyip karıştırın.',
        'Vanilya ve tuzu ekleyin.',
        'Un ve kakaoyu eleyerek karışıma ekleyin ve spatula yardımıyla yavaşça karıştırın.',
        'İsteğe bağlı olarak çikolata parçalarını ekleyin.',
        'Karışımı hazırladığınız fırın kabına dökün.',
        'Önceden ısıtılmış fırında 25-30 dakika pişirin. Ortası hafif ıslak kalmalı.',
        'Fırından çıkarıp en az 1 saat oda sıcaklığında soğutun ve dilimleyerek servis yapın.'
      ],
      nutrition: {
        calories: '420 kcal',
        fat: '24g',
        protein: '5g',
        carbs: '45g',
        fiber: '2g',
        sugar: '32g'
      }
    }
  ];
  
  useEffect(() => {
    // API'den tarifi çekme işlemi burada yapılacak
    setLoading(true);
    
    // Şimdilik örnek verilerle çalışıyoruz
    setTimeout(() => {
      const selectedRecipe = exampleRecipes.find(r => r.id === recipeId);
      
      if (selectedRecipe) {
        setRecipe(selectedRecipe);
        
        // İlgili tarifleri bul (aynı kategorilerdeki diğer tarifler)
        const related = exampleRecipes.filter(r => 
          r.id !== recipeId && 
          r.categories.some(c => selectedRecipe.categories.map(sc => sc.id).includes(c.id))
        ).slice(0, 3);
        
        setRelatedRecipes(related);
      }
      
      setLoading(false);
    }, 500);
  }, [recipeId]);
  
  // Zorluk seviyesinin Türkçe karşılığı
  const getDifficultyText = (difficulty) => {
    switch (difficulty) {
      case 'easy':
        return 'Kolay';
      case 'medium':
        return 'Orta';
      case 'hard':
        return 'Zor';
      default:
        return '';
    }
  };
  
  // Zorluk seviyesine göre CSS sınıfı
  const getDifficultyClass = (difficulty) => {
    switch (difficulty) {
      case 'easy':
        return 'easy';
      case 'medium':
        return 'medium';
      case 'hard':
        return 'hard';
      default:
        return '';
    }
  };
  
  if (loading) {
    return <PageContainer>Yükleniyor...</PageContainer>;
  }
  
  if (!recipe) {
    return (
      <PageContainer>
        <h2>Tarif Bulunamadı</h2>
        <p>Aradığınız tarif mevcut değil veya kaldırılmış olabilir.</p>
        <Link to="/recipes">Tariflere Dön</Link>
      </PageContainer>
    );
  }
  
  return (
    <PageContainer>
      <RecipeHeader>
        <RecipeImageContainer>
          <RecipeImage src={recipe.image} alt={recipe.title} />
        </RecipeImageContainer>
        
        <RecipeInfo>
          <RecipeTitle>{recipe.title}</RecipeTitle>
          <RecipeDifficulty className={getDifficultyClass(recipe.difficulty)}>
            {getDifficultyText(recipe.difficulty)}
          </RecipeDifficulty>
          <RecipeDescription>{recipe.description}</RecipeDescription>
          
          <RecipeMeta>
            <MetaItem>⏱️ Hazırlama: {recipe.time}</MetaItem>
            <MetaItem>👥 Porsiyon: {recipe.servings}</MetaItem>
          </RecipeMeta>
          
          <RecipePrice>Tahmini Maliyet: {recipe.price}</RecipePrice>
          
          <RecipeAuthor>Tarif: {recipe.author} | {new Date(recipe.date).toLocaleDateString()}</RecipeAuthor>
          
          <div>
            {recipe.categories.map(category => (
              <CategoryTag key={category.id} to={`/category/${category.id}`}>
                {category.name}
              </CategoryTag>
            ))}
          </div>
        </RecipeInfo>
      </RecipeHeader>
      
      <RecipeTabs>
        <TabsHeader>
          <TabButton 
            active={activeTab === 'ingredients'} 
            onClick={() => setActiveTab('ingredients')}
          >
            Malzemeler
          </TabButton>
          <TabButton 
            active={activeTab === 'instructions'} 
            onClick={() => setActiveTab('instructions')}
          >
            Yapılışı
          </TabButton>
          <TabButton 
            active={activeTab === 'nutrition'} 
            onClick={() => setActiveTab('nutrition')}
          >
            Besin Değerleri
          </TabButton>
        </TabsHeader>
        
        <TabContent active={activeTab === 'ingredients'}>
          <IngredientsSection>
            <SectionTitle>Malzeme Listesi</SectionTitle>
            <IngredientsList>
              {recipe.ingredients.map((ingredient, index) => (
                <IngredientItem key={index}>{ingredient}</IngredientItem>
              ))}
            </IngredientsList>
          </IngredientsSection>
        </TabContent>
        
        <TabContent active={activeTab === 'instructions'}>
          <InstructionsSection>
            <SectionTitle>Yapılış Adımları</SectionTitle>
            <StepsList>
              {recipe.instructions.map((step, index) => (
                <StepItem key={index}>{step}</StepItem>
              ))}
            </StepsList>
          </InstructionsSection>
        </TabContent>
        
        <TabContent active={activeTab === 'nutrition'}>
          <NutritionSection>
            <SectionTitle>Besin Değerleri</SectionTitle>
            <NutritionTable>
              <thead>
                <TableRow>
                  <TableHeader>Besin Değeri</TableHeader>
                  <TableHeader>Miktar (porsiyon başına)</TableHeader>
                </TableRow>
              </thead>
              <tbody>
                <TableRow>
                  <TableCell>Kalori</TableCell>
                  <TableCell>{recipe.nutrition.calories}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Yağ</TableCell>
                  <TableCell>{recipe.nutrition.fat}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Protein</TableCell>
                  <TableCell>{recipe.nutrition.protein}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Karbonhidrat</TableCell>
                  <TableCell>{recipe.nutrition.carbs}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Lif</TableCell>
                  <TableCell>{recipe.nutrition.fiber}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Şeker</TableCell>
                  <TableCell>{recipe.nutrition.sugar}</TableCell>
                </TableRow>
              </tbody>
            </NutritionTable>
          </NutritionSection>
        </TabContent>
      </RecipeTabs>
      
      {relatedRecipes.length > 0 && (
        <RelatedRecipes>
          <RelatedTitle>Benzer Tarifler</RelatedTitle>
          <RecipesGrid>
            {relatedRecipes.map(relatedRecipe => (
              <RecipeCard key={relatedRecipe.id}>
                <RecipeCardImage src={relatedRecipe.image} alt={relatedRecipe.title} />
                <RecipeCardContent>
                  <RecipeCardTitle>{relatedRecipe.title}</RecipeCardTitle>
                  <ViewRecipeButton to={`/recipes/${relatedRecipe.id}`}>
                    Tarifi Görüntüle
                  </ViewRecipeButton>
                </RecipeCardContent>
              </RecipeCard>
            ))}
          </RecipesGrid>
        </RelatedRecipes>
      )}
    </PageContainer>
  );
};

export default RecipeDetailPage;
